import {canonicalCanvas as canonical} from './canonical.mjs';
import React from 'react';import {createRoot} from 'react-dom/client';import {createMemoryRouter,RouterProvider} from 'react-router-dom';
import {ConfigProvider,App as AntApp} from 'antd';import zhCN from 'antd/es/locale/zh_CN';import {QueryClient,QueryClientProvider} from '@tanstack/react-query';
import 'antd/dist/reset.css';import 'streamdown/styles.css';import '@/styles/globals.css';import '@/i18n';
import CanvasPage from '@/pages/canvas/project';import {useCanvasStore} from '@/stores/canvas/use-canvas-store';
import {useConfigStore,defaultConfig,encodeChannelModel} from '@/stores/use-config-store';import {stores} from './memory';import {notify} from './rpc';
import {uploadImage} from '@/services/image-storage';import {createCanvasNode,imageMetadata} from '@/lib/canvas/canvas-node-factory';import {CanvasNodeType} from '@/types/canvas';
async function encode(value:any):Promise<any>{if(value instanceof Blob){const bytes=new Uint8Array(await value.arrayBuffer());let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return {__asBlob:true,type:value.type,base64:btoa(binary)};}if(Array.isArray(value))return Promise.all(value.map(encode));if(value&&typeof value==='object')return Object.fromEntries(await Promise.all(Object.entries(value).map(async([k,v])=>[k,await encode(v)])));return value;}
function decode(value:any):any{if(value?.__asBlob)return new Blob([Uint8Array.from(atob(value.base64),c=>c.charCodeAt(0))],{type:value.type});if(Array.isArray(value))return value.map(decode);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,decode(v)]));return value;}
export async function mount(snapshot:any,providers:any[],selected:any){for(const [key,rows]of snapshot?.stores||[]){let map=stores.get(key);if(!map){map=new Map();stores.set(key,map);}map.clear();for(const [k,v]of rows)map.set(k,decode(v));}if(snapshot?.projects)useCanvasStore.setState({projects:snapshot.projects,deletedProjects:[],hydrated:true});else{useCanvasStore.setState({hydrated:true});useCanvasStore.getState().createProject('新效果圖畫布');}
 const channels=providers.map(p=>({id:p.id,name:p.label,baseUrl:'https://company-gateway.invalid',apiKey:'SERVER-MANAGED-NOT-A-KEY',apiFormat:'openai' as const,models:[...new Set([p.model,...p.models].filter(Boolean))].map(name=>({name,capability:'image' as const}))}));const model=selected?.provider&&channels.some(c=>c.id===selected.provider)?encodeChannelModel(selected.provider,selected.model):'';
 useConfigStore.setState({config:{...defaultConfig,channels,models:channels.flatMap(c=>c.models.map(m=>encodeChannelModel(c.id,m.name))),model,imageModel:model,count:'1',canvasImageCount:'1'},isConfigOpen:false,openConfigDialog:()=>notify('notice',{message:'請在AS Workspace左下選擇模型；供應商設定由管理員管理。'})});

 let dirtySequence=0,previous=canonical(useCanvasStore.getState().projects);useCanvasStore.subscribe(s=>{const next=canonical(s.projects);if(next!==previous){previous=next;notify('dirty',{sequence:++dirtySequence});}});
 const channelHandler=(e:MessageEvent)=>{const d=e.data;if(d.type==='command'&&d.action==='snapshot')void (async()=>{const sequence=dirtySequence;const persistent=[...stores].filter(([name])=>['image_files','image_generation_logs'].includes(name));const result={schema:1,projects:useCanvasStore.getState().projects,stores:await Promise.all(persistent.map(async([name,map])=>[name,await Promise.all([...map].map(async([k,v])=>[k,await encode(v)]))]))};notify('snapshot',{id:d.id,snapshot:result,sequence});})();if(d.type==='command'&&d.action==='model'){const v=d.selected?.provider?encodeChannelModel(d.selected.provider,d.selected.model):'';useConfigStore.setState(s=>({config:{...s.config,model:v,imageModel:v}}));}if(d.type==='command'&&d.action==='insert-image')void(async()=>{try{const image=await uploadImage(new Blob([d.bytes],{type:d.mime})),p=useCanvasStore.getState().projects[0];if(!p)return;const node=createCanvasNode(CanvasNodeType.Image,{x:300,y:300},{...imageMetadata(image),companySource:{fileId:d.fileId,version:d.version}} as any);window.dispatchEvent(new CustomEvent('as-canvas-insert-image',{detail:node}));}catch(e){notify('notice',{message:String(e)});}})();};
 // RPC installs the response handler; commands are dispatched separately.
 window.addEventListener('as-canvas-command',((e:CustomEvent)=>channelHandler({data:e.detail} as MessageEvent)) as EventListener);
 const initial=useCanvasStore.getState().projects[0]?.id;const router=createMemoryRouter([{path:'/canvas/:id',element:<CanvasPage/>},{path:'*',element:<CanvasPage/>}],{initialEntries:['/canvas/'+initial]});
 document.body.style.margin='0';document.documentElement.style.height='100%';document.body.style.height='100%';document.getElementById('root')!.style.height='100%';createRoot(document.getElementById('root')!).render(<ConfigProvider locale={zhCN}><AntApp style={{height:"100%"}}><QueryClientProvider client={new QueryClient()}><div style={{height:'100%',display:'flex',flexDirection:'column'}}><small style={{padding:4}}>Infinite Canvas · basketikun · 公司整合版（圖片／文字／配置／群組；影片與插件未開放）</small><div style={{flex:1,minHeight:0}}><RouterProvider router={router}/></div></div></QueryClientProvider></AntApp></ConfigProvider>);
}
